// ── Metro-map skill trees: map/list toggle and progress ────────
// The layout comes from the page's front matter (generated by
// _scripts/metro_layout.py). Progress lives in this browser's localStorage
// only, one key per tree.
(function () {
  'use strict';

  const root = document.querySelector('[data-tree]');
  const dataEl = document.getElementById('metro-data');
  if (!root || !dataEl) return;
  const storeKey = 'lt-skilltree:' + root.dataset.tree;
  const data = JSON.parse(dataEl.textContent);
  const metro = data.metro;
  const SVG_NS = 'http://www.w3.org/2000/svg';

  // ── Storage (may be unavailable: private windows, blocked storage) ──
  function loadDone() {
    try { return new Set(JSON.parse(localStorage.getItem(storeKey)) || []); }
    catch (e) { return new Set(); }
  }
  function saveDone(set) {
    try { localStorage.setItem(storeKey, JSON.stringify(Array.from(set))); }
    catch (e) { /* progress just won't persist */ }
  }
  function loadPref(key) {
    try { return localStorage.getItem(key); } catch (e) { return null; }
  }
  function savePref(key, value) {
    try { localStorage.setItem(key, value); } catch (e) { /* ignore */ }
  }

  let done = loadDone();

  function setDone(id, isDone) {
    done = loadDone();   // another tab may have changed it
    if (isDone) done.add(id); else done.delete(id);
    saveDone(done);
    refresh();
  }

  // ── List view checkboxes ───────────────────────────────────
  const boxes = Array.from(document.querySelectorAll('input[type="checkbox"][data-skill]'));
  boxes.forEach(function (box) {
    box.closest('label').hidden = false;
    box.addEventListener('change', function () { setDone(box.dataset.skill, box.checked); });
  });

  // ── Map ────────────────────────────────────────────────────
  function el(name, attrs, parent) {
    const node = document.createElementNS(SVG_NS, name);
    Object.keys(attrs || {}).forEach(function (k) { node.setAttribute(k, attrs[k]); });
    if (parent) parent.appendChild(node);
    return node;
  }

  const byId = {};
  metro.stations.forEach(function (st) { byId[st.id] = st; });
  const colorOf = {};
  metro.lines.forEach(function (ln) { colorOf[ln.topic] = ln.color; });
  const nameOf = function (id) { return byId[id] ? byId[id].label.join(' ') : id; };
  const stops = [];   // { id, group, toggle } for refreshing done state
  const stopGroups = {};   // id -> station <g>, for the "also needs" highlight

  function drawMap(container) {
    if (!metro || !metro.stations || !metro.stations.length) return false;
    const svg = el('svg', {
      viewBox: '0 0 ' + metro.width + ' ' + metro.height,
      width: metro.width,
      height: metro.height,
      role: 'group',
      'aria-label': 'Skill map',
      class: 'metro-svg'
    }, container);

    // Lines: each gets a casing in the page color, so a later line crossing
    // an earlier one shows a small gap, as on a printed metro map.
    const gLines = el('g', {}, svg);
    metro.lines.forEach(function (ln) {
      el('path', { d: ln.d, class: 'metro-casing' }, gLines);
      el('path', { d: ln.d, class: 'metro-line', stroke: ln.color }, gLines);
    });
    const gStops = el('g', {}, svg);
    // Drawn last so "also needs" links sit on top of everything.
    const gNeeds = el('g', { class: 'metro-needs' }, svg);
    el('defs', {}, svg).innerHTML =
      '<marker id="metro-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto">' +
      '<path d="M0,0 L10,5 L0,10 z" class="metro-arrow"/></marker>';
    metro.stations.forEach(function (st) {
      const color = colorOf[st.topic];
      const name = st.label.join(' ');
      const url = data.urls[st.id];
      const group = el('g', { class: 'metro-stop' + (st.start ? ' metro-start' : '') }, gStops);
      const r = st.start ? 11 : 8;

      // Label above the station: a link once the skill has a page.
      const link = url ? el('a', { href: url }, group) : el('g', { class: 'metro-pending' }, group);
      el('title', {}, link).textContent = name + (url ? '' : ' (coming soon)') +
        (st.also ? '\nAlso needs: ' + st.also.map(nameOf).join(', ') : '');
      const text = el('text', { x: st.x, 'text-anchor': 'middle', class: 'metro-label' }, link);
      st.label.forEach(function (line, i) {
        el('tspan', { x: st.x, y: st.y - r - 8 - (st.label.length - 1 - i) * 13 }, text).textContent = line;
      });
      if (st.start) {
        el('text', { x: st.x - r - 10, y: st.y + 4, 'text-anchor': 'end', class: 'metro-start-tag' }, group)
          .textContent = 'START HERE';
      }

      // The station itself is the done toggle.
      if (st.workshop) el('circle', { cx: st.x, cy: st.y, r: r + 5, class: 'metro-ws' }, group);
      const toggle = el('g', {
        class: 'metro-toggle',
        role: 'checkbox',
        tabindex: '0',
        'aria-label': 'Done: ' + name,
        style: '--line: ' + color
      }, group);
      el('title', {}, toggle).textContent = 'Mark "' + name + '" as done';
      el('circle', { cx: st.x, cy: st.y, r: r }, toggle);
      el('text', { x: st.x, y: st.y + 4, 'text-anchor': 'middle' }, toggle).textContent = '✓';
      function flip() { setDone(st.id, !done.has(st.id)); }
      toggle.addEventListener('click', flip);
      toggle.addEventListener('keydown', function (e) {
        if (e.key === ' ' || e.key === 'Enter') { e.preventDefault(); flip(); }
      });
      group.addEventListener('pointerenter', function () { showNeeds(st); });
      group.addEventListener('pointerleave', hideNeeds);
      group.addEventListener('focusin', function () { showNeeds(st); });
      group.addEventListener('focusout', hideNeeds);
      stops.push({ id: st.id, group: group, toggle: toggle });
      stopGroups[st.id] = group;
    });

    // ── "Also needs": curved links from each extra prerequisite to the station ──
    function curve(a, b, trimA, trimB) {
      const dx = b.x - a.x, dy = b.y - a.y, len = Math.hypot(dx, dy) || 1;
      const ux = dx / len, uy = dy / len;
      const ax = a.x + ux * trimA, ay = a.y + uy * trimA, bx = b.x - ux * trimB, by = b.y - uy * trimB;
      const bend = Math.min(80, len * 0.2);
      const cx = (ax + bx) / 2 - uy * bend, cy = (ay + by) / 2 + ux * bend;
      return 'M' + ax.toFixed(1) + ',' + ay.toFixed(1) + ' Q' + cx.toFixed(1) + ',' + cy.toFixed(1) +
        ' ' + bx.toFixed(1) + ',' + by.toFixed(1);
    }
    function showNeeds(st) {
      hideNeeds();
      if (!st.also) return;
      stopGroups[st.id].classList.add('metro-focus');
      st.also.forEach(function (id) {
        const need = byId[id];
        if (!need) return;
        stopGroups[id].classList.add('metro-need');
        const d = curve(need, st, need.start ? 16 : 13, st.start ? 18 : 15);
        el('path', { d: d, class: 'metro-need-halo' }, gNeeds);
        el('path', { d: d, class: 'metro-need-link', 'marker-end': 'url(#metro-arrow)' }, gNeeds);
      });
    }
    function hideNeeds() {
      gNeeds.innerHTML = '';
      svg.querySelectorAll('.metro-focus, .metro-need').forEach(function (g) {
        g.classList.remove('metro-focus', 'metro-need');
      });
    }
    return true;
  }

  // ── Progress ───────────────────────────────────────────────
  const progressEl = document.getElementById('skilltree-progress');

  function refresh() {
    stops.forEach(function (s) {
      s.group.classList.toggle('done', done.has(s.id));
      s.toggle.setAttribute('aria-checked', done.has(s.id));
    });
    boxes.forEach(function (box) { box.checked = done.has(box.dataset.skill); });
    if (!progressEl) return;
    const n = metro.stations.filter(function (st) { return done.has(st.id); }).length;
    progressEl.textContent = n + ' of ' + metro.stations.length + ' done';
    if (n) {
      const reset = document.createElement('button');
      reset.className = 'skilltree-reset';
      reset.textContent = 'reset';
      reset.addEventListener('click', function () {
        if (!confirm('Clear your progress on this map?')) return;
        done = new Set();
        saveDone(done);
        refresh();
      });
      progressEl.append(' · ', reset);
    }
  }

  // ── Map / list toggle ──────────────────────────────────────
  const mapView = document.getElementById('metro-map');
  const mapCanvas = document.getElementById('metro-canvas');
  const listView = document.getElementById('metro-list');
  const viewButtons = Array.from(document.querySelectorAll('[data-view]'));
  const viewKey = 'lt-metro-view';

  function setView(view) {
    mapView.hidden = view !== 'map';
    listView.hidden = view !== 'list';
    viewButtons.forEach(function (b) { b.classList.toggle('active', b.dataset.view === view); });
  }

  if (drawMap(mapCanvas)) {
    viewButtons.forEach(function (b) {
      b.hidden = false;
      b.addEventListener('click', function () { savePref(viewKey, b.dataset.view); setView(b.dataset.view); });
    });
    // Phones get the list by default; the map is wide.
    setView(loadPref(viewKey) || (window.innerWidth < 640 ? 'list' : 'map'));
  }
  refresh();

})();
